    wc.globalAlpha=0.45*fade; wc.strokeStyle='#ffffff'; wc.lineWidth=1.2; wc.beginPath(); wc.ellipse(x,y,R*0.88,R*0.53,0,0,6.2832); wc.stroke();
    for(j=0;j<5;j++){   // five soft clouds that drift round the middle
